import { useState } from "react";
import { useNavigate } from "react-router-dom";
import ForgotPasswordPopup from "./ForgotPasswordPopup";

const API = "http://localhost:5000/api/auth";

const inputStyle = (focus) => ({
  width: "100%",
  height: "48px",
  padding: "0 14px",
  border: `1.5px solid ${focus ? "rgb(148, 0, 211)" : "#e0c8f8"}`,
  borderRadius: "8px",
  outline: "none",
  background: focus ? "#f5eaff" : "#fdf8ff",
  marginBottom: "14px",
  fontSize: "14px",
});

export default function Login() {
  const navigate = useNavigate();

  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);

  const [loginMode, setLoginMode] = useState("password"); // password | otp

  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [showPw, setShowPw] = useState(false);
  const [showForgot, setShowForgot] = useState(false);

  // ---------------- PASSWORD LOGIN ----------------
  const handleLogin = async () => {
    setError("");

    if (!identifier || !password) {
      return setError("Email/Phone and Password required");
    }

    setLoading(true);

    try {
      const res = await fetch(`${API}/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ identifier, password }),
      });

      const data = await res.json();

      if (data.success) {
        localStorage.setItem("token", data.token);
        navigate("/home");
      } else {
        setError(data.message);
      }
    } catch {
      setError("Server error");
    }

    setLoading(false);
  };

  // ---------------- SEND OTP ----------------
  const sendLoginOtp = async () => {
    setError("");

    if (!identifier) {
      return setError("Email/Phone required");
    }

    try {
      const res = await fetch(`${API}/send-login-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: identifier }), // ⚠️ backend expects email
      });

      const data = await res.json();

      if (data.success) {
        setOtpSent(true);
      } else {
        setError(data.message);
      }
    } catch {
      setError("OTP send failed");
    }
  };

  // ---------------- VERIFY OTP ----------------
  const verifyLoginOtp = async () => {
    setError("");

    try {
      const res = await fetch(`${API}/verify-login-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: identifier, // ⚠️ IMPORTANT FIX (backend mismatch fix)
          otp,
        }),
      });

      const data = await res.json();

      if (data.success) {
        localStorage.setItem("token", data.token);
        navigate("/home");
      } else {
        setError(data.message);
      }
    } catch {
      setError("OTP verify failed");
    }
  };

  return (
    <div className="main-container">

      {/* LEFT */}
      <div className="login-left">
        <h2>TheZuro</h2>
      </div>

      {/* RIGHT */}
      <div className="login-right">

        <h2>Welcome Back 👋</h2>

        {error && <p style={{ color: "red" }}>{error}</p>}

        {/* identifier */}
        <input
          style={inputStyle(false)}
          placeholder="Email or Phone"
          value={identifier}
          onChange={(e) => setIdentifier(e.target.value)}
        />

        {/* ---------------- PASSWORD MODE ---------------- */}
        {loginMode === "password" && (
          <>
            <div style={{ position: "relative" }}>
              <input
                style={inputStyle(false)}
                type={showPw ? "text" : "password"}
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />

              <span onClick={() => setShowPw(!showPw)}>
                {showPw ? "🙈" : "👁"}
              </span>
            </div>

            <button onClick={handleLogin}>
              Login
            </button>
          </>
        )}

        {/* ---------------- OTP MODE ---------------- */}
        {loginMode === "otp" && (
          <>
            {!otpSent ? (
              <button onClick={sendLoginOtp}>
                Send OTP
              </button>
            ) : (
              <>
                <input
                  style={inputStyle(false)}
                  placeholder="Enter OTP"
                  value={otp}
                  onChange={(e) => setOtp(e.target.value)}
                />

                <button onClick={verifyLoginOtp}>
                  Verify OTP
                </button>
              </>
            )}
          </>
        )}

        {/* MODE SWITCH */}
        <div style={{ marginTop: 10 }}>
          {loginMode === "password" ? (
            <button onClick={() => setLoginMode("otp")}>
              OTP Login
            </button>
          ) : (
            <button onClick={() => setLoginMode("password")}>
              Password Login
            </button>
          )}
        </div>

        <p onClick={() => setShowForgot(true)}>
          Forgot Password?
        </p>

        {showForgot && (
          <ForgotPasswordPopup onClose={() => setShowForgot(false)} />
        )}
      </div>


      
    </div>
  );
}
